using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using A2A.Client;
using A2A.Json;
using A2A.Signing;

namespace A2A.Tests;

/// <summary>Agent Card canonicalization and signatures checked against vectors generated by a2a-python 1.2.1 (see Vectors/README.md).</summary>
public class CanonicalizationVectorTests
{
    private static readonly string VectorDir = Path.Combine(AppContext.BaseDirectory, "Vectors", "card-signing");

    public static TheoryData<string> VectorNames => new()
    {
        "minimal", "full", "empty-optionals", "false-capabilities", "unicode", "extension-params", "mixed-version",
    };

    private static string Read(string file) => File.ReadAllText(Path.Combine(VectorDir, file), Encoding.UTF8);

    private static JsonObject ReadObject(string file) => JsonNode.Parse(Read(file))!.AsObject();

    private static string Canonical(JsonObject card) => Encoding.UTF8.GetString(AgentCardCanonicalizer.Canonicalize(card));

    [Theory]
    [MemberData(nameof(VectorNames))]
    public void Canonical_bytes_match_python(string name)
    {
        var expected = File.ReadAllBytes(Path.Combine(VectorDir, $"{name}.canonical.txt"));
        Assert.Equal(Encoding.UTF8.GetString(expected), Canonical(ReadObject($"{name}.input.json")));
        Assert.Equal(expected, AgentCardCanonicalizer.Canonicalize(ReadObject($"{name}.input.json")));
        // The card as a2a-python serves it (signatures, v0.3 compatibility fields) has the same canonical form.
        Assert.Equal(Encoding.UTF8.GetString(expected), Canonical(ReadObject($"{name}.signed.json")));
    }

    [Theory]
    [MemberData(nameof(VectorNames))]
    public async Task Python_signatures_verify(string name)
    {
        // The vectors' keys are pinned for the origin the vectors were served from (their jku host).
        var jwks = JsonSerializer.Deserialize(Read("keys.jwks.json"), A2AJson.GetTypeInfo<JwkSet>())!;
        var verifier = new AgentCardVerifier(SigningTests.Trust([.. jwks.Keys]));
        var signed = ReadObject($"{name}.signed.json");

        var result = await verifier.VerifyAsync(signed, SigningTests.CardUri);

        Assert.Equal(AgentCardVerificationStatus.Verified, result.Status);
        Assert.Equal(SigningTests.Origin, result.Issuer);
        // Every signature verifies on its own.
        foreach (var signature in signed["signatures"]!.AsArray())
        {
            var single = (JsonObject)signed.DeepClone();
            single["signatures"] = new JsonArray(signature!.DeepClone());
            var one = await verifier.VerifyAsync(single, SigningTests.CardUri);
            Assert.Equal(AgentCardVerificationStatus.Verified, one.Status);
            Assert.StartsWith("py-", one.KeyId);
        }
    }

    [Theory]
    [MemberData(nameof(VectorNames))]
    public void Model_round_trip_keeps_the_canonical_form(string name)
    {
        // What the signer signs: the input deserialized into the model and serialized again.
        var card = A2AJson.Deserialize<AgentCard>(Read($"{name}.input.json"))!;
        Assert.Equal(Read($"{name}.canonical.txt"), Canonical(AgentCardCanonicalizer.ToNode(card)));
    }

    private static AgentCard CardWithPrunableValues()
    {
        var card = SigningTests.SampleCard();
        card.SecuritySchemes = new() { ["bearer"] = SecurityScheme.Bearer() };
        card.SecurityRequirements = [new SecurityRequirement { Schemes = { ["bearer"] = new StringList() } }];
        card.Skills = [];
        return card;
    }

    [Fact]
    public async Task Signer_signs_card_with_prunable_values_and_it_verifies()
    {
        var key = new AgentCardSigningKey(System.Security.Cryptography.ECDsa.Create(System.Security.Cryptography.ECCurve.NamedCurves.nistP256), "k1", "ES256");

        var signed = AgentCardSigner.Sign(CardWithPrunableValues(), key);

        var json = A2AJson.Serialize(signed);
        Assert.Contains("\"skills\":[]", json);
        var verifier = new AgentCardVerifier(SigningTests.Trust(key.ToPublicJwk()));
        Assert.Equal(AgentCardVerificationStatus.Verified, (await verifier.VerifyAsync(json, SigningTests.CardUri)).Status);
    }

    [Fact]
    public void Pruned_paths_lists_values_the_signature_does_not_cover()
    {
        Assert.Equal(
            ["$.securityRequirements[0].schemes.bearer.list", "$.skills"],
            AgentCardCanonicalizer.PrunedPaths(AgentCardCanonicalizer.ToNode(CardWithPrunableValues())));
    }

    [Fact]
    public async Task Fully_populated_model_card_signs_and_loses_nothing_to_canonicalization()
    {
        // Guards against a model field the canonicalizer's schema does not know: such a field would be silently unsigned.
        // PrunedPaths is empty only if every model member survives canonicalization.
        var card = A2AJson.Deserialize<AgentCard>(Read("full.input.json"))!;
        // The vector has scope-less requirements ("list": []), which a2a-python prunes; give them scopes.
        card.SecurityRequirements![1].Schemes["mtls"].List = ["client"];
        card.Skills[0].SecurityRequirements![0].Schemes["bearer"].List = ["read"];
        card.SecuritySchemes!["client"] = new OAuth2Scheme(
            new OAuth2SecurityScheme
            {
                Flows = new OAuthFlows
                {
                    ClientCredentials = new ClientCredentialsOAuthFlow
                    {
                        TokenUrl = "https://auth.example/token", RefreshUrl = "https://auth.example/refresh", Scopes = new() { ["read"] = "Read" },
                    },
                },
            });
        var key = new AgentCardSigningKey(System.Security.Cryptography.ECDsa.Create(System.Security.Cryptography.ECCurve.NamedCurves.nistP256), "k1", "ES256");

        var signed = AgentCardSigner.Sign(card, key);

        var node = AgentCardCanonicalizer.ToNode(card);
        Assert.Empty(AgentCardCanonicalizer.PrunedPaths(node));
        Assert.Equal(JsonCanonicalizer.CanonicalizeToString(node.ToJsonString()), Canonical(node));
        var verifier = new AgentCardVerifier(SigningTests.Trust(key.ToPublicJwk()));
        Assert.Equal(AgentCardVerificationStatus.Verified, (await verifier.VerifyAsync(A2AJson.Serialize(signed), SigningTests.CardUri)).Status);
    }

    [Fact]
    public void Proto_defaults_are_dropped_only_where_a2a_python_drops_them()
    {
        var card = JsonNode.Parse("""
        {"name":"n","capabilities":{"streaming":false,"extensions":[{"uri":"u","required":false,"params":{"required":false,"n":0,"s":"","z":null}}]},
         "securitySchemes":{"o":{"oauth2SecurityScheme":{"flows":{"authorizationCode":{"tokenUrl":"t","pkceRequired":false}}}}}}
        """)!.AsObject();
        Assert.Equal(
            """{"capabilities":{"extensions":[{"params":{"n":0,"required":false},"uri":"u"}],"streaming":false},"name":"n","securitySchemes":{"o":{"oauth2SecurityScheme":{"flows":{"authorizationCode":{"tokenUrl":"t"}}}}}}""",
            Canonical(card));
    }
}

public class CaseVariantMemberTests
{
    private static readonly AgentCardSigningKey Key =
        new(System.Security.Cryptography.ECDsa.Create(System.Security.Cryptography.ECCurve.NamedCurves.nistP256), "k1", "ES256");

    private static string SignedRaw() => A2AJson.Serialize(AgentCardSigner.Sign(SigningTests.SampleCard(), Key));

    private static string Inject(string raw, Action<JsonObject> change)
    {
        var node = JsonNode.Parse(raw)!.AsObject();
        change(node);
        return node.ToJsonString();
    }

    private static readonly JsonObject AttackerSchemes = new()
    {
        ["evil"] = new JsonObject
        {
            ["oauth2SecurityScheme"] = new JsonObject
            {
                ["flows"] = new JsonObject { ["clientCredentials"] = new JsonObject { ["tokenUrl"] = "https://attacker.example/token" } },
            },
        },
    };

    public static TheoryData<string, string> Injections => new()
    {
        { "absent-top-level", "$.IconUrl" },
        { "absent-security-schemes", "$.SecuritySchemes" },
        { "present-name", "$.Name" },
        { "nested-tenant", "$.supportedInterfaces[0].Tenant" },
        { "signatures-variant", "$.Signatures" },
    };

    private static string Injected(string kind) => Inject(SignedRaw(), n =>
    {
        switch (kind)
        {
            case "absent-top-level": n["IconUrl"] = "https://attacker.example/icon.png"; break;
            case "absent-security-schemes": n["SecuritySchemes"] = AttackerSchemes.DeepClone(); break;
            case "present-name": n["Name"] = "Evil"; break;
            case "nested-tenant": n["supportedInterfaces"]![0]!["Tenant"] = "attacker"; break;
            case "signatures-variant": n["Signatures"] = new JsonArray(); break;
        }
    });

    [Theory]
    [MemberData(nameof(Injections))]
    public async Task Case_variant_member_makes_a_signed_card_invalid(string kind, string path)
    {
        var raw = Injected(kind);
        Assert.Equal([path], AgentCardCanonicalizer.CaseVariantMembers(JsonNode.Parse(raw)!.AsObject()));

        var result = await new AgentCardVerifier(SigningTests.Trust(Key.ToPublicJwk())).VerifyAsync(raw, SigningTests.CardUri);

        Assert.Equal(AgentCardVerificationStatus.Failed, result.Status);
        Assert.Contains($"'{path}'", result.Reason);
    }

    [Theory]
    [MemberData(nameof(Injections))]
    public async Task Resolver_never_returns_an_injected_value(string kind, string path)
    {
        _ = path;
        var resolver = Resolver(Injected(kind));
        // Verification rejects it; on net10 a duplicate like "Name"/"name" is already rejected as malformed when parsed.
        await Assert.ThrowsAnyAsync<A2AException>(() => resolver.ResolveAsync(new Uri("https://agent.example/")));
    }

    [Fact]
    public async Task Resolver_builds_a_verified_card_from_the_signed_content()
    {
        var resolved = await Resolver(SignedRaw()).ResolveAsync(new Uri("https://agent.example/"));

        Assert.Equal(AgentCardVerificationStatus.Verified, resolved.Verification.Status);
        Assert.Equal("Signer", resolved.Card.Name);
        Assert.Equal("https://agent.example/a2a", resolved.Card.SupportedInterfaces[0].Url);
        Assert.Single(resolved.Card.Signatures!);
    }

    [Fact]
    public async Task Resolver_accepts_a_verified_card_whose_empty_required_lists_were_pruned()
    {
        var card = SigningTests.SampleCard();
        card.Skills = [];
        card.DefaultInputModes = [];
        card.DefaultOutputModes = [];
        var raw = A2AJson.Serialize(AgentCardSigner.Sign(card, Key));
        // The signed (pruned) content omits the empty lists, so the model is built without them.
        Assert.DoesNotContain("\"skills\"", AgentCardCanonicalizer.SignedContent(JsonNode.Parse(raw)!.AsObject()).ToJsonString());

        var resolved = await Resolver(raw).ResolveAsync(new Uri("https://agent.example/"));

        Assert.Equal(AgentCardVerificationStatus.Verified, resolved.Verification.Status);
        Assert.Empty(resolved.Card.Skills);
        Assert.Empty(resolved.Card.DefaultInputModes);
    }

    private static A2ACardResolver Resolver(string cardJson) => new(
        new HttpClient(new StaticCardHandler(cardJson)),
        new A2ACardResolverOptions { Trust = SigningTests.Trust(Key.ToPublicJwk()) });

    private sealed class StaticCardHandler(string json) : HttpMessageHandler
    {
        protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken) =>
            Task.FromResult(new HttpResponseMessage(System.Net.HttpStatusCode.OK)
            {
                Content = new StringContent(json, Encoding.UTF8, "application/json"),
            });
    }
}
